// Past Perfect, and combining narrative tenses to tell stories.
// Same standard as earlier months: 3 teaching sections + 3 stages of 10
// exercises (easy B1 -> mid B1 -> B1/B2 stretch).
//
// IDs use the month scheme (m5dNN = May, day NN). 31 lessons across weeks
// 18-22 (positions 120-150 in LESSON_SEQUENCE). Weeks 18-21 are full 7-lesson
// weeks; week 22 carries the final 3 (days 148-150), continuing into June.
import type { LessonDef } from './lessonData'

